query:
mutation sitesCreateWifiSsid ( $accountId:ID! $createWifiSsidInput:CreateWifiSsidInput!) {
	sites ( accountId:$accountId ) {
		createWifiSsid ( input:$createWifiSsidInput  )  {
			wifiSsid {
				id
				networkInterfaceId
				site {
					id
					name
				}
				name
				enabled
				category
				visible
				subnet
				localIp
				dhcp {
					dhcpSubnet
				}
				vlanId
				dhcpEnabled
				microsegmentationEnabled
				internetOnly
				mdnsEnabled
				security {
					mode
					authProtocol
					trackAuthentication
				}
				band
			}
		}
	}	
}
